+    private static String reservationWith(String identification) {
+        return """
+                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
+                 %s "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 2, "ratePlan": "STANDARD"}
+                """.formatted(identification);
+    }
+
+    @Test
+    void acceptsACompanyOrAForeignGuestAndNullsTheRest() throws Exception {
+        HttpResponse<String> company = post("/reservations",
+                reservationWith("\"companyCnpj\": \"12.345.678/0001-90\", \"companyName\": \"Tecnosul Ltda\","));
+        assertEquals(201, company.statusCode());
+        JsonNode created = json.readTree(company.body());
+        assertEquals("Tecnosul Ltda", created.get("companyName").asText());
+        assertTrue(created.get("guestCpf").isNull());
+        assertTrue(created.get("guestPassport").isNull());
+
+        HttpResponse<String> foreigner = post("/reservations", reservationWith(
+                "\"guestPassport\": \"X1234567\", \"guestCountry\": \"United Kingdom\",").replace("201", "202"));
+        assertEquals(201, foreigner.statusCode());
+        long id = json.readTree(foreigner.body()).get("id").asLong();
+        post("/reservations/" + id + "/confirmation", "");
+        JsonNode document = json.readTree(get("/reservations/" + id + "/document").body());
+        assertEquals("Booking receipt", document.get("title").asText());
+        assertEquals("United Kingdom", document.get("guestCountry").asText());
+        assertTrue(document.get("guestCpf").isNull());
+        assertTrue(document.get("companyCnpj").isNull());
+        assertTrue(document.get("text").asText().startsWith("Booking receipt no. " + id));
+        assertTrue(json.readTree(get("/reservations/" + id).body()).get("companyName").isNull());
+    }
+
+    @Test
+    void requiresExactlyOneWayToIdentifyTheGuest() throws Exception {
+        for (String identification : new String[] {
+            "",
+            "\"companyCnpj\": \"12.345.678/0001-90\",",
+            "\"guestPassport\": \"X1234567\",",
